/**
 * Authority cells (grammar design §8.3): forms Allen & Greenough's 1903 print shows, transcribed by hand from the page
 * scans each file names; never generated by the engine. Every printed form of a cell must be generated for its target
 * (macron-sensitive), an `unavailable` cell must generate nothing, and an `excluded` form must not be generated.
 */
import { readdirSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { untaggedExtras } from '../../scripts/corpus/model.ts';
import { resolvedTargetKey } from '../../src/catalogue.js';
import { conjugate } from '../../src/index.js';
import { quantityProblems } from '../../src/languages/la/orthography.js';

interface Target {
  readonly verb: string; readonly mood: string; readonly tense?: string; readonly voice?: string; readonly subject?: string;
  readonly agreement?: Readonly<Record<string, string>>;
}
interface Cell extends Target { readonly forms: readonly string[]; readonly unavailable?: boolean; readonly printed?: string; readonly usage?: string }
interface Note extends Target { readonly printed: string; readonly other?: string; readonly reason: string }
interface AuthorityFile {
  readonly work: string; readonly section: string; readonly pages: string; readonly scan: readonly string[];
  readonly cells: readonly Cell[]; readonly excluded: readonly Note[]; readonly disputed: readonly Note[];
  readonly transcribedBy: string; readonly checkedAgainst: string;
}

const directory = new URL('../goldens/la/authority/', import.meta.url);
const names = readdirSync(directory).filter(name => name.endsWith('.json')).sort();
const files = names.map(name => ({ name, ...(JSON.parse(readFileSync(new URL(name, directory), 'utf8')) as AuthorityFile) }));

function generate(target: Target) {
  const { verb, mood, tense, voice, subject, agreement } = target;
  return conjugate({
    language: 'la', infinitive: verb, mood, ...(tense === undefined ? {} : { tense }), ...(voice === undefined ? {} : { voice }),
    ...(subject === undefined ? {} : { subject }), ...(agreement === undefined ? {} : { agreement }),
  } as never);
}
const label = (target: Target): string =>
  [target.verb, target.mood, target.tense, target.voice, target.subject, target.agreement && JSON.stringify(target.agreement)].filter(Boolean).join(' ');

describe('Latin authority cells (A&G 1903)', () => {
  it.each(files)('$name', ({ cells, excluded, disputed, scan, section, transcribedBy, checkedAgainst }) => {
    expect(scan.length).toBeGreaterThan(0);
    expect([section, transcribedBy, checkedAgainst].every(text => text.length > 0)).toBe(true);
    for (const cell of cells) {
      const result = generate(cell);
      const texts = result.forms.map(form => form.text);
      if (cell.unavailable) {
        expect(texts, `${label(cell)} is unavailable`).toEqual([]);
        continue;
      }
      for (const printed of cell.forms) expect(texts, `${label(cell)}: ${printed}`).toContain(printed);
      // A form the print does not show must carry a variant tag (usage or pattern), as in the scraped-corpus guard.
      expect(untaggedExtras(result.forms, cell.forms, resolvedTargetKey).map(form => form.text), `${label(cell)}: untagged extras`).toEqual([]);
      if (cell.usage) {
        for (const printed of cell.forms) expect(result.forms.find(form => form.text === printed)!.variant.usage, `${label(cell)}: ${printed}`).toBe(cell.usage);
      }
    }
    for (const note of excluded) {
      expect(note.reason.length).toBeGreaterThan(30);
      expect(generate(note).forms.map(form => form.text), `${label(note)}: ${note.printed} is excluded`).not.toContain(note.printed);
    }
    for (const note of disputed) {
      expect(note.reason.length).toBeGreaterThan(30);
      expect(generate(note).forms.map(form => form.text), `${label(note)}: ${note.other}`).toContain(note.other);
    }
  });

  it('admits only forms that pass the quantity lint', () => {
    for (const { cells } of files) {
      for (const cell of cells) for (const text of cell.forms) for (const word of text.split(' ')) expect(quantityProblems(word), word).toEqual([]);
    }
  });

  it('pins the transcription', () => {
    expect(names).toHaveLength(13);
    expect(files.reduce((sum, file) => sum + file.cells.length, 0)).toBe(1_249);
    expect(files.reduce((sum, file) => sum + file.cells.filter(cell => cell.unavailable).length, 0)).toBe(21);
  });
});
